#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.340654, -0.234242915, -0.017180654999999996], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.06703956, 'zmax': 0.06703956, 'profiles': [{'outer': [[-0.087226475, -0.034045135000000004], [-0.092329475, -0.026290595000000028], [-0.09543132499999998, -0.017385305000000018], [-0.09623179500000001, -0.010431204999999999], [-0.095631455, -0.006378775000000003], [-0.094130575, -2.506499999999079e-05], [-0.090628505, 0.006929035], [-0.080072275, 0.018335815000000005], [-0.07281800499999999, 0.02298852500000001], [-0.065213505, 0.02538990499999999], [-0.056959969251857936, 0.02705632284935952], [-0.050204654999999994, 0.02909213499999999], [-0.044251155, 0.034095075], [-0.04044890499999999, 0.043250504999999995], [-0.03844771499999999, 0.054857405], [-0.037697274999999995, 0.06666439499999999], [-0.037297054999999996, 0.08477496500000001], [-0.036946855, 0.090078145], [-0.036346505, 0.09338006499999998], [-0.035345905, 0.09533113499999998], [-0.03389505499999999, 0.096281795], [-0.028491854999999996, 0.09918349499999998], [-0.026840884999999995, 0.099383535], [-0.015434144999999996, 0.100434305], [0.0013757850000000044, 0.09933361499999999], [0.020837275000000002, 0.096481975], [0.03959834500000001, 0.092479585], [0.054457105, 0.08787682499999999], [0.05570785500000001, 0.08727642499999999], [0.06426289500000001, 0.082523765], [0.06516344500000001, 0.081222985], [0.066614285, 0.07697042500000001], [0.066814405, 0.07486921499999999], [0.066063965, 0.071517195], [0.064162835, 0.066464215], [0.056608395, 0.049304125000000004], [0.052055695000000006, 0.037747265], [0.04885382500000001, 0.02569010499999999], [0.048513807556558014, 0.0151985639688217], [0.052205795000000006, 0.008179815000000007], [0.059410045, 0.0019261250000000008], [0.076670245, -0.009230464999999993], [0.085325345, -0.01633465500000003], [0.09227945500000001, -0.02463960500000001], [0.09603167500000001, -0.03364485500000003], [0.09623179500000001, -0.035445895000000005], [0.09583154499999999, -0.04530179499999998], [0.09032831499999999, -0.055557785000000026], [0.08122294499999999, -0.06516349500000002], [0.07882150500000001, -0.06691449500000002], [0.068765575, -0.07396873500000001], [0.059159915, -0.07782092499999999], [0.051055125, -0.07792100499999999], [0.044201095, -0.07481914500000003], [0.038497725000000003, -0.06946605500000003], [0.033644855, -0.063262345], [0.029492395000000005, -0.057659035000000025], [0.025740195000000007, -0.05335652499999999], [0.023051931485811493, -0.051387684727439716], [0.023538925000000002, -0.05420708499999999], [0.025139865000000004, -0.06066089499999999], [0.026490685000000007, -0.06786513500000002], [0.026840885000000002, -0.07066673499999998], [0.027291145000000003, -0.078221235], [0.026040415000000004, -0.08547544499999998], [0.022488315000000002, -0.09172922500000003], [0.015984475000000005, -0.09638193500000003], [0.013182825000000006, -0.097482595], [0.003927355000000004, -0.09993404500000003], [-0.007329294999999996, -0.100434305], [-0.018535904999999995, -0.09868335500000003], [-0.027941465, -0.094931125], [-0.03474548499999999, -0.08932784500000002], [-0.039148075, -0.081923425], [-0.041599525, -0.07321834500000002], [-0.04245004499999999, -0.06416297500000001], [-0.042400005, -0.05585807500000001], [-0.041999774999999996, -0.048453634999999995], [-0.042049804999999996, -0.04214996500000001], [-0.043250514999999996, -0.037697254999999985], [-0.04504724235444403, -0.03684796824707042], [-0.048153394999999995, -0.039248225000000025], [-0.052305855, -0.04189977500000003], [-0.057458894999999996, -0.043800805], [-0.068715535, -0.04475140500000002], [-0.074218785, -0.043350635000000026], [-0.082423635, -0.038797945]], 'holes': []}], 'simplify_tolerance': 4.0173722000000005e-05, 'sketch_entity_count': 93}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
